head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_MxDataSet",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";
        // MxDataSet_code1.reset();
        $c.cm.PanelToGroupBox_01(panel_1);
        scwin.setCode();

        // fn_code1_sync();
        // toDaySet(txb_date);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT70100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT70100.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description btn_cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_cal_onclick = function() {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT70100.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sys_search_onclick = async function() {
    try {
        if (cyear.getText() !== "" && cmonth.getText() !== "") {
            await scwin.listSync(); // alert();

        } else if (cyear.getText() === "") {
            await $c.win.alert("년도를 지정하십시요");
            cyear.focus();
        } else if (cmonth.getText() === "") {
            await $c.win.alert("월을 지정하십시요");
            cmonth.focus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT70100.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_rollusr_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_rollusr_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT70100.btn_rollusr_save_onclick" });
    }
};

/**
 * @method
 * @name MxLogicalTr_OnFail
 * @description Mx Logical Tr On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxLogicalTr_OnFail = async function() {
    try {
        await $c.win.alert('저장을 실패했습니다');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT70100.MxLogicalTr_OnFail" });
    }
};

/**
 * @method
 * @name MxLogicalTr_OnSuccess
 * @description Mx Logical Tr On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxLogicalTr_OnSuccess = async function() {
    try {
        await $c.win.alert('저장하였습니다');
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT70100.MxLogicalTr_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/calnd.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    MxLogicalTr.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_MxLogicalTr",
        action : "/calnd.do",
        ref : "MxDataSet",
        target : "MxLogicalTr=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    const ToDay = new Date();
    scwin.setYear(ToDay);
    scwin.setMonth(ToDay);
};

/**
 * @method
 * @name setYear
 * @description set Year 처리
 * @param {*} ToDay ToDay
 * @returns {void}
 * @hidden N
 */
scwin.setYear = function(ToDay) {
    const yyyy = parseInt(ToDay.getYear(), 10) + 20;
    let str = "";
    for (let i = yyyy; i >= 2007; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cyear.CBData = str;
    cyear.setSelectedIndex(20);
};

/**
 * @method
 * @name setMonth
 * @description set Month 처리
 * @param {*} ToDay ToDay
 * @returns {void}
 * @hidden N
 */
scwin.setMonth = function(ToDay) {
    // alert(cmonth.ListCount);
    cmonth.setSelectedIndex(ToDay.getMonth());
};
